import { randomUUID } from 'node:crypto';
import type { Router } from 'express';
import { z } from 'zod';
import { idempotency } from '../lib/idempotency.ts';
import { CursorQuerySchema, encodeCursor, pageSchema, paginate } from '../lib/pagination.ts';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';

const UserRoleSchema = z.enum(['admin', 'member']);
const UserSchema = z.object({
  id: z.uuid(),
  email: z.email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});
const CreateUserSchema = UserSchema.omit({ id: true, createdAt: true, updatedAt: true }).extend({
  role: UserRoleSchema.default('member'),
});
const UpdateUserSchema = CreateUserSchema.partial().refine((value) => Object.keys(value).length > 0, { message: 'patch: At least one field must be provided' });
const UserParamsSchema = z.object({ userId: z.uuid() });

export function registerRoutes(app: Router): void {
  const users = new Map<string, z.infer<typeof UserSchema>>();

  app.get('/v1/users', (req, res) => {
    const query = CursorQuerySchema.parse(req.query);
    const page = paginate([...users.values()], query, (user) => `${user.createdAt}|${user.id}`);
    res.json(pageSchema(UserSchema).parse(page));
  });

  app.post('/v1/users', idempotency(), (req, res) => {
    const body = CreateUserSchema.parse(req.body);
    for (const user of users.values()) if (user.email === body.email) throw conflict('email already exists', 'duplicate-email');
    const now = new Date().toISOString();
    const user = UserSchema.parse({ id: randomUUID(), createdAt: now, updatedAt: now, ...body });
    users.set(user.id, user);
    res.status(201).location(`/v1/users/${user.id}`).json(UserSchema.parse(user));
  });

  app.get('/v1/users/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const user = users.get(userId);
    if (user === undefined) throw notFound(`user ${userId} not found`);
    res.json(UserSchema.parse(user));
  });

  app.patch('/v1/users/:userId', idempotency(), (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const existing = users.get(userId);
    if (existing === undefined) throw notFound(`user ${userId} not found`);
    const patch = UpdateUserSchema.parse(req.body);
    if (patch.email !== undefined) for (const user of users.values()) if (user.id !== userId && user.email === patch.email) throw conflict('email already exists', 'duplicate-email');
    const updated = UserSchema.parse({ ...existing, ...patch, updatedAt: new Date().toISOString() });
    users.set(userId, updated);
    res.json(UserSchema.parse(updated));
  });

  app.delete('/v1/users/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    if (!users.delete(userId)) throw notFound(`user ${userId} not found`);
    res.status(204).end();
  });
}

