  id: z.uuid(),
  email: z.email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});
const CreateUserSchema = UserSchema.omit({ id: true, createdAt: true, updatedAt: true }).extend({
  role: UserRoleSchema.default('member'),
});
const UpdateUserSchema = z
  .object({
    email: z.email().optional(),
    name: z.string().min(1).max(100).optional(),
    role: UserRoleSchema.optional(),
  })
  .refine((value) => Object.keys(value).length > 0, { message: 'patch: At least one field must be provided' });
const UserParamsSchema = z.object({ userId: z.uuid() });

export function registerRoutes(app: Router): void {
  const users = new Map<string, z.infer<typeof UserSchema>>();

  app.get('/v1/users', (req, res) => {
    const query = CursorQuerySchema.parse(req.query);
    const page = paginate([...users.values()], query, (user) => `${user.createdAt}|${user.id}`);
    res.json(pageSchema(UserSchema).parse(page));
  });

  app.post('/v1/users', idempotency(), (req, res) => {
    const body = CreateUserSchema.parse(req.body);
    for (const user of users.values()) if (user.email === body.email) throw conflict('email already exists', 'duplicate-email');
