    users.set(user.id, user);
    res.status(201).location(`/v1/users/${user.id}`).json(UserSchema.parse(user));
  });

  app.get('/v1/users/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const user = users.get(userId);
    if (user === undefined) throw notFound(`user ${userId} not found`);
    res.json(UserSchema.parse(user));
  });

  app.patch('/v1/users/:userId', idempotency(), (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const existing = users.get(userId);
    if (existing === undefined) throw notFound(`user ${userId} not found`);
    const patch = UpdateUserSchema.parse(req.body);
    if (patch.email !== undefined) for (const user of users.values()) if (user.id !== userId && user.email === patch.email) throw conflict('email already exists', 'duplicate-email');
    const updated = UserSchema.parse({ ...existing, ...patch, updatedAt: new Date().toISOString() });
    users.set(userId, updated);
    res.json(UserSchema.parse(updated));
  });

  app.delete('/v1/users/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    if (!users.delete(userId)) throw notFound(`user ${userId} not found`);
    res.status(204).end();
  });
}

